+      }
+    } else if (f instanceof Object && f.type === undefined) {
+      for (var n in f) {
+        var r = f[n];
+        if (typeof r == "function") {
+          o[t][n] = typeof r();
+        } else if (r instanceof Object && r.type !== undefined) {
