+      }
+    } else if (f instanceof Object && f.type !== undefined) {
+      if (f.type == "ObjectId") {
+        o[t] = "One " + f.ref;
+      } else {
+        o[t] = {
+          ...e[t]
+        };
+        o[t].type = typeof f.type();
+      }
+    }
+  }
+  return o;
+};
